import{_ as c}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as h,D as s,o,c as u,I as n,w as f,k as r,a as m,R as d,b as k,e as g}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const M=JSON.parse('{"title":"消息队列与 MQ 核心知识","description":"异步、解耦、削峰、交付语义与 Kafka 和传统消息队列的差别，用订单案例理解消息队列的核心概念。","frontmatter":{"title":"消息队列与 MQ 核心知识","date":"2026-11-05T00:00:00.000Z","category":"Java课程","tags":["Java","Kafka","MQ"],"description":"异步、解耦、削峰、交付语义与 Kafka 和传统消息队列的差别，用订单案例理解消息队列的核心概念。"},"headers":[],"relativePath":"courses/java/16-Kafka/02-消息队列与MQ核心知识.md","filePath":"courses/java/16-Kafka/02-消息队列与MQ核心知识.md","lastUpdated":1793885095000}'),b={name:"courses/java/16-Kafka/02-消息队列与MQ核心知识.md"},_=r("h1",{id:"消息队列与-mq-核心知识",tabindex:"-1"},[m("消息队列与 MQ 核心知识 "),r("a",{class:"header-anchor",href:"#消息队列与-mq-核心知识","aria-label":'Permalink to "消息队列与 MQ 核心知识"'},"​")],-1),q=d(`<h2 id="为什么需要消息队列" tabindex="-1">为什么需要消息队列 <a class="header-anchor" href="#为什么需要消息队列" aria-label="Permalink to &quot;为什么需要消息队列&quot;">​</a></h2><p>先看一个没有消息队列的场景：</p><p><strong>订单服务直接调用三个下游</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>用户下单</span></span>
<span class="line"><span>  → 订单服务写数据库（10ms）</span></span>
<span class="line"><span>    → 调用库存服务扣库存（50ms）</span></span>
<span class="line"><span>      → 调用通知服务发短信（200ms）</span></span>
<span class="line"><span>        → 调用报表服务更新统计（100ms）</span></span></code></pre></div><p>总耗时：10 + 50 + 200 + 100 = 360ms。用户等了 360ms 才看到&quot;下单成功&quot;。如果通知服务的短信网关抖动到 3 秒，用户就等 3 秒多——但发短信真的需要让用户等吗？</p><p>引入消息队列后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>用户下单</span></span>
<span class="line"><span>  → 订单服务写数据库（10ms）</span></span>
<span class="line"><span>    → 发送 OrderCreated 事件到 Kafka（5ms）</span></span>
<span class="line"><span>      → 返回&quot;下单成功&quot;给用户（总计 15ms）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同时，三个下游各自从 Kafka 读取事件：</span></span>
<span class="line"><span>  → 库存服务消费 → 扣库存</span></span>
<span class="line"><span>  → 通知服务消费 → 发短信</span></span>
<span class="line"><span>  → 报表服务消费 → 更新统计</span></span></code></pre></div><p>用户只等 15ms，三个下游各自独立处理，互不影响。这就是消息队列的核心价值。</p><h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to &quot;核心术语&quot;">​</a></h2><table><thead><tr><th>术语</th><th>含义</th><th>快递站类比</th></tr></thead><tbody><tr><td><strong>消息（message）</strong></td><td>一次业务事实或命令，通常含 key、value、时间戳和 headers</td><td>一个包裹</td></tr><tr><td><strong>Topic</strong></td><td>消息的逻辑名称；Kafka Topic 由多个分区组成</td><td>一个货架分类</td></tr><tr><td><strong>分区（partition）</strong></td><td>有序追加日志，顺序只在单个分区内有保证</td><td>货架上的一列</td></tr><tr><td><strong>offset</strong></td><td>分区内消息的位置编号，不是全局唯一序号</td><td>包裹在列中的位置号</td></tr><tr><td><strong>消费组（consumer group）</strong></td><td>组内实例分工读分区；不同组各读一份</td><td>不同快递员各自取件</td></tr><tr><td><strong>Producer</strong></td><td>发送消息到 Topic 的客户端</td><td>寄件人</td></tr><tr><td><strong>Consumer</strong></td><td>从 Topic 读取消息的客户端</td><td>取件人</td></tr><tr><td><strong>Broker</strong></td><td>Kafka 服务端节点，存储消息并提供读写</td><td>快递站本身</td></tr></tbody></table><h2 id="什么时候用消息队列" tabindex="-1">什么时候用消息队列 <a class="header-anchor" href="#什么时候用消息队列" aria-label="Permalink to &quot;什么时候用消息队列&quot;">​</a></h2><p>消息队列解决三类问题：</p><h3 id="_1-异步处理-缩短用户等待" tabindex="-1">1. 异步处理：缩短用户等待 <a class="header-anchor" href="#_1-异步处理-缩短用户等待" aria-label="Permalink to &quot;1. 异步处理：缩短用户等待&quot;">​</a></h3><p>如上面的订单案例，把不需要同步等待的操作改为异步消费。判断标准是：<strong>这个操作的结果用户需要立即看到吗？</strong> 发短信、更新统计、记录日志——用户不需要等。扣库存——如果是&quot;先扣再下单&quot;，用户需要知道是否有库存。</p><h3 id="_2-解耦-生产方不需要知道所有下游" tabindex="-1">2. 解耦：生产方不需要知道所有下游 <a class="header-anchor" href="#_2-解耦-生产方不需要知道所有下游" aria-label="Permalink to &quot;2. 解耦：生产方不需要知道所有下游&quot;">​</a></h3><p>订单服务只需要发出 <code>OrderCreated</code> 事件，不需要知道有几个下游在消费。新增一个&quot;风控审计&quot;服务只需要创建新的消费组订阅同一 Topic，订单服务一行代码都不用改。</p><p>如果没有消息队列，订单服务要直接调用每个下游。新增一个下游就要改订单服务代码、加调用逻辑、处理超时和重试——这叫硬编码耦合。</p><h3 id="_3-削峰-缓冲流量尖峰" tabindex="-1">3. 削峰：缓冲流量尖峰 <a class="header-anchor" href="#_3-削峰-缓冲流量尖峰" aria-label="Permalink to &quot;3. 削峰：缓冲流量尖峰&quot;">​</a></h3><p>秒杀场景下每秒 10 万订单，数据库扛不住直接写入。让 Producer 先把消息发到 Kafka（Kafka 每秒可处理百万级消息），消费者按照数据库能承受的速率（比如每秒 1 万）平滑消费。消息在 Kafka 中短暂积压，但数据库不会被打垮。</p><p><strong>但消息队列也带来新问题</strong>：消息会晚到、可能重复、可能积压。不能把同步事务的成功直接等同于消息链路成功。</p><h2 id="消息不能替代同步调用" tabindex="-1">消息不能替代同步调用 <a class="header-anchor" href="#消息不能替代同步调用" aria-label="Permalink to &quot;消息不能替代同步调用&quot;">​</a></h2><p>什么时候不该用消息队列？</p><ul><li><strong>需要立即获得结果</strong>：查询商品价格、计算订单金额——用户等着看结果，不能用异步。</li><li><strong>结果必须确定</strong>：支付扣款——必须等扣款成功才能告诉用户&quot;已支付&quot;，不能发完消息就说&quot;支付成功&quot;。</li><li><strong>操作极简单且量小</strong>：直接 HTTP 调用比维护一个 Kafka 集群简单得多。</li></ul><h2 id="kafka-的多消费组模型" tabindex="-1">Kafka 的多消费组模型 <a class="header-anchor" href="#kafka-的多消费组模型" aria-label="Permalink to &quot;Kafka 的多消费组模型&quot;">​</a></h2><p>Kafka 和传统消息队列有一个重要区别：<strong>同一条消息可以被多个消费组各自读取</strong>。</p>`,25),E=d(`<p>同一个消费组分摊分区，不同消费组各自保留独立的消费进度。如果只有两个分区，同一组开五个实例也不会让五个实例同时处理五个分区——多出的实例会空闲。</p><p>传统队列（如 RabbitMQ）的消息被一个消费者取走后就删除了，其他消费者看不到。Kafka 的消息不会因消费而删除，而是按保留期（默认 7 天）持久存储。这就是为什么 Kafka 适合&quot;事件流&quot;场景：多个下游各自独立读取同一份数据。</p><h2 id="交付语义" tabindex="-1">交付语义 <a class="header-anchor" href="#交付语义" aria-label="Permalink to &quot;交付语义&quot;">​</a></h2><p>消息的投递保证有三种语义，理解它们对正确设计业务至关重要：</p><h3 id="最多一次-at-most-once" tabindex="-1">最多一次（at-most-once） <a class="header-anchor" href="#最多一次-at-most-once" aria-label="Permalink to &quot;最多一次（at-most-once）&quot;">​</a></h3><p>消息可能丢失，但不会重复。Producer 发出去不等确认（<code>acks=0</code>），或者消费者处理前先提交 offset。</p><ul><li><strong>适用</strong>：日志上报、监控指标——丢几条没关系。</li><li><strong>风险</strong>：业务消息可能丢失。</li></ul><h3 id="至少一次-at-least-once" tabindex="-1">至少一次（at-least-once） <a class="header-anchor" href="#至少一次-at-least-once" aria-label="Permalink to &quot;至少一次（at-least-once）&quot;">​</a></h3><p>消息不会丢失，但可能重复。Producer 等确认并重试（<code>acks=all</code>），消费者处理完再提交 offset。</p><ul><li><strong>适用</strong>：大多数业务场景——订单、支付、库存。</li><li><strong>风险</strong>：重复消息需要业务侧做幂等处理。</li><li><strong>Kafka 默认实践</strong>：Producer 开启 <code>acks=all</code> + <code>enable.idempotence=true</code>，Consumer 关闭自动提交、处理完手动提交。</li></ul><h3 id="恰好一次-exactly-once" tabindex="-1">恰好一次（exactly-once） <a class="header-anchor" href="#恰好一次-exactly-once" aria-label="Permalink to &quot;恰好一次（exactly-once）&quot;">​</a></h3><p>消息不丢不重。需要 Kafka 事务 + 消费者读取-处理-写入都在同一事务内。</p><ul><li><strong>适用</strong>：Kafka 内部的流处理（Kafka Streams）。</li><li><strong>限制</strong>：Kafka 事务只覆盖 Kafka 内部读写，不能自动保证外部数据库的恰好一次。如果消费者先写 MySQL 再提交 offset，两步不在同一事务中，崩溃时可能出现不一致。</li></ul><h3 id="实务中的选择" tabindex="-1">实务中的选择 <a class="header-anchor" href="#实务中的选择" aria-label="Permalink to &quot;实务中的选择&quot;">​</a></h3><p>绝大多数业务使用&quot;至少一次 + 业务幂等&quot;：</p><ul><li>消费者用 <code>orderId</code> 做唯一约束或幂等记录表。</li><li>收到重复消息时，检查 <code>orderId</code> 是否已处理过——已处理则跳过。</li><li>这样即使消息重投，业务效果也只产生一次。</li></ul><h3 id="幂等处理的具体例子" tabindex="-1">幂等处理的具体例子 <a class="header-anchor" href="#幂等处理的具体例子" aria-label="Permalink to &quot;幂等处理的具体例子&quot;">​</a></h3><p>假设消费者收到 <code>OrderCreated(orderId=O-7)</code> 后要扣库存：</p><ol><li>第一次收到：检查 <code>O-7</code> 未处理 → 扣库存 → 记录 <code>O-7 已处理</code> → 提交 offset</li><li>第二次收到（重复投递）：检查 <code>O-7</code> 已处理 → 跳过 → 提交 offset</li></ol><p>&quot;记录已处理&quot;可以是一张 <code>processed_events</code> 表，用 <code>eventId</code> 做主键。写入和业务操作放在同一数据库事务中，保证要么一起成功要么一起失败。</p><h2 id="崩溃时会发生什么" tabindex="-1">崩溃时会发生什么 <a class="header-anchor" href="#崩溃时会发生什么" aria-label="Permalink to &quot;崩溃时会发生什么&quot;">​</a></h2><p>理解下面的崩溃场景，才能真正明白消息可靠性：</p><h3 id="场景一-先更新数据库-再提交-offset" tabindex="-1">场景一：先更新数据库，再提交 offset <a class="header-anchor" href="#场景一-先更新数据库-再提交-offset" aria-label="Permalink to &quot;场景一：先更新数据库，再提交 offset&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>1. 消费者收到消息 → 处理 → 更新 MySQL 成功</span></span>
<span class="line"><span>2. 提交 offset 前，消费者崩溃</span></span>
<span class="line"><span>3. 重启后从上次提交的 offset 继续 → 再次处理同一条消息</span></span></code></pre></div><p>结果：数据库被更新了两次。如果没有幂等，库存扣了两次。这就是为什么必须做幂等。</p><h3 id="场景二-先提交-offset-再更新数据库" tabindex="-1">场景二：先提交 offset，再更新数据库 <a class="header-anchor" href="#场景二-先提交-offset-再更新数据库" aria-label="Permalink to &quot;场景二：先提交 offset，再更新数据库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span>1. 消费者收到消息 → 提交 offset</span></span>
<span class="line"><span>2. 更新 MySQL 前，消费者崩溃</span></span>
<span class="line"><span>3. 重启后从新 offset 继续 → 跳过这条消息</span></span></code></pre></div><p>结果：消息被标记为已消费但业务没执行。这就是为什么&quot;先提交再处理&quot;会丢业务效果——不能用这种方式换取&quot;不重复&quot;。</p><h3 id="正确做法" tabindex="-1">正确做法 <a class="header-anchor" href="#正确做法" aria-label="Permalink to &quot;正确做法&quot;">​</a></h3><p>先处理业务（在数据库事务中同时写幂等记录），再提交 offset。崩溃时最坏情况是重复处理，但幂等保证了业务安全。</p><h2 id="kafka-和传统-mq-的关注点" tabindex="-1">Kafka 和传统 MQ 的关注点 <a class="header-anchor" href="#kafka-和传统-mq-的关注点" aria-label="Permalink to &quot;Kafka 和传统 MQ 的关注点&quot;">​</a></h2><table><thead><tr><th>关注点</th><th>Kafka</th><th>传统 MQ（RabbitMQ / ActiveMQ）</th></tr></thead><tbody><tr><td>消息生命周期</td><td>按保留期持久存储，消费后不删除</td><td>消费后删除</td></tr><tr><td>多组独立读</td><td>不同消费组各自保留 offset，独立读取</td><td>一条消息只投递一次</td></tr><tr><td>消息重放</td><td>可以按 offset 重新读取历史消息</td><td>不支持，消息已删除</td></tr><tr><td>顺序保证</td><td>分区内有序</td><td>队列内有序</td></tr><tr><td>吞吐量</td><td>极高（顺序磁盘写 + 零拷贝）</td><td>中等</td></tr><tr><td>路由模型</td><td>Topic + 分区 + key 路由</td><td>Exchange + Queue + Binding</td></tr><tr><td>适用场景</td><td>事件流、日志、监控、CDC</td><td>任务队列、RPC 路由、延迟队列</td></tr></tbody></table><p>JMS 是 Java 消息 API 规范，AMQP 是消息协议；Kafka 提供自己的分区日志与客户端协议。两者都能异步解耦，选择时看是否需要重放、多组独立读取、顺序范围、吞吐与运维能力，而不是只比较&quot;能不能发消息&quot;。<a href="https://kafka.apache.org/documentation/#design" target="_blank" rel="noreferrer">Kafka 设计文档</a>。</p>`,33);function P(a,A,C,v,B,K){const l=c,i=s("ClientOnly"),p=s("Mermaid");return o(),u("div",null,[_,n(i,null,{default:f(()=>{var t,e;return[(((t=a.$frontmatter)==null?void 0:t.aside)??!0)&&(((e=a.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(o(),k(l,{key:0,article:a.$frontmatter},null,8,["article"])):g("",!0)]}),_:1}),q,n(p,{id:"mermaid_64a56ebc",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E8%AE%A2%E5%8D%95%E6%9C%8D%E5%8A%A1%20Producer%5D%20--%3E%7COrderCreated%2C%20key%3Dorder-7%7C%20T%5BTopic%3A%20order.events%5D%0A%20%20%20%20T%20--%3E%20P0%5B%E5%88%86%E5%8C%BA%200%EF%BC%9A%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%E5%92%8C%20offset%5D%0A%20%20%20%20T%20--%3E%20P1%5B%E5%88%86%E5%8C%BA%201%EF%BC%9A%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%E5%92%8C%20offset%5D%0A%20%20%20%20P0%20--%3E%20G1%5B%E5%BA%93%E5%AD%98%E6%B6%88%E8%B4%B9%E7%BB%84%5D%0A%20%20%20%20P1%20--%3E%20G1%0A%20%20%20%20P0%20--%3E%20G2%5B%E9%80%9A%E7%9F%A5%E6%B6%88%E8%B4%B9%E7%BB%84%5D%0A%20%20%20%20P1%20--%3E%20G2"}),E])}const Q=h(b,[["render",P]]);export{M as __pageData,Q as default};
